pub struct ContentIdentity {
    pub identity: String,
}
impl crate::bedrock::codec::BedrockSized for ContentIdentity {
    fn encoded_size(&self) -> usize {
        let mut size = 0usize;
        size += {
            let _len = (&self.identity).as_bytes().len();
            crate::bedrock::codec::BedrockSized::encoded_size(&crate::bedrock::codec::VarInt(
                _len as i32,
            )) + _len
        };
        size
    }
}
impl crate::bedrock::codec::BedrockCodec for ContentIdentity {
    type Args = ();
    fn encode<B: bytes::BufMut>(&self, buf: &mut B) -> Result<(), std::io::Error> {
        let _ = buf;
        let bytes = (&self.identity).as_bytes();
        let len = bytes.len();
        crate::bedrock::codec::VarInt(len as i32).encode(buf)?;
        buf.put_slice(bytes);
        Ok(())
    }
    fn decode<B: bytes::Buf>(
        buf: &mut B,
        _args: Self::Args,
    ) -> Result<Self, crate::bedrock::error::DecodeError> {
        let _ = buf;
        let identity = {
            let len_raw =
                (<crate::bedrock::codec::VarInt as crate::bedrock::codec::BedrockCodec>::decode(
                    buf,
                    (),
                )?
                .0) as i64;
            if len_raw < 0 {
                return Err(crate::bedrock::error::DecodeError::NegativeLength { value: len_raw });
            }
            let len = len_raw as usize;
            if buf.remaining() < len {
                return Err(crate::bedrock::error::DecodeError::StringLengthExceeded {
                    declared: len,
                    available: buf.remaining(),
                });
            }
            let mut bytes = vec![0u8; len];
            buf.copy_to_slice(&mut bytes);
            crate::bedrock::codec::decode_utf8_lossy_owned(bytes)
        };
        Ok(Self { identity })
    }
}
