pub struct CorrectPlayerMovePredictionPacketPayload {
    pub prediction_type: CorrectPlayerMovePredictionPacketPayloadPredictionTypeVariant,
    pub pos: Vec3,
    pub pos_delta: Vec3,
    pub rotation: Vec2,
    pub vehicle_angular_velocity: Option<f32>,
    pub on_ground: bool,
    pub tick: PlayerInputTick,
}
impl crate::bedrock::codec::BedrockSized for CorrectPlayerMovePredictionPacketPayload {
    fn encoded_size(&self) -> usize {
        let mut size = 0usize;
        size += crate::bedrock::codec::BedrockSized::encoded_size(&self.prediction_type);
        size += crate::bedrock::codec::BedrockSized::encoded_size(&self.pos);
        size += crate::bedrock::codec::BedrockSized::encoded_size(&self.pos_delta);
        size += crate::bedrock::codec::BedrockSized::encoded_size(&self.rotation);
        size += {
            1usize
                + match &self.vehicle_angular_velocity {
                    Some(_v) => 4usize,
                    None => 0usize,
                }
        };
        size += 1usize;
        size += crate::bedrock::codec::BedrockSized::encoded_size(&self.tick);
        size
    }
}
impl crate::bedrock::codec::BedrockCodec for CorrectPlayerMovePredictionPacketPayload {
    type Args = ();
    fn encode<B: bytes::BufMut>(&self, buf: &mut B) -> Result<(), std::io::Error> {
        let _ = buf;
        self.prediction_type.encode(buf)?;
        self.pos.encode(buf)?;
        self.pos_delta.encode(buf)?;
        self.rotation.encode(buf)?;
        match &self.vehicle_angular_velocity {
            Some(v) => {
                buf.put_u8(1);
                crate::bedrock::codec::F32LE(*v).encode(buf)?;
            }
            None => buf.put_u8(0),
        }
        self.on_ground.encode(buf)?;
        self.tick.encode(buf)?;
        Ok(())
    }
    fn decode<B: bytes::Buf>(
        buf: &mut B,
        _args: Self::Args,
    ) -> Result<Self, crate::bedrock::error::DecodeError> {
        let _ = buf;
        let prediction_type = <CorrectPlayerMovePredictionPacketPayloadPredictionTypeVariant as crate::bedrock::codec::BedrockCodec>::decode(
            buf,
            (),
        )?;
        let pos = <Vec3 as crate::bedrock::codec::BedrockCodec>::decode(buf, ())?;
        let pos_delta = <Vec3 as crate::bedrock::codec::BedrockCodec>::decode(buf, ())?;
        let rotation = <Vec2 as crate::bedrock::codec::BedrockCodec>::decode(buf, ())?;
        let vehicle_angular_velocity = {
            let present = u8::decode(buf, ())?;
            if present != 0 {
                Some(
                    <crate::bedrock::codec::F32LE as crate::bedrock::codec::BedrockCodec>::decode(
                        buf,
                        (),
                    )?
                    .0,
                )
            } else {
                None
            }
        };
        let on_ground = <bool as crate::bedrock::codec::BedrockCodec>::decode(buf, ())?;
        let tick = <PlayerInputTick as crate::bedrock::codec::BedrockCodec>::decode(buf, ())?;
        Ok(Self {
            prediction_type,
            pos,
            pos_delta,
            rotation,
            vehicle_angular_velocity,
            on_ground,
            tick,
        })
    }
}
